	protected static function doOnDeleteCascade(Criteria $criteria, PropelPDO $con)
	{
		// initialize var to track total num of affected rows
		$affectedRows = 0;

		// first find the objects that are implicated by the $criteria
		$objects = Tb011CuentaBancariaPeer::doSelect($criteria, $con);
		foreach ($objects as $obj) {


			// delete related Tb100BancoLibro objects
			$c = new Criteria(Tb100BancoLibroPeer::DATABASE_NAME);
			
			$c->add(Tb100BancoLibroPeer::ID_TB011_CUENTA_BANCARIA, $obj->getCoCuentaBancaria());
			$affectedRows += Tb100BancoLibroPeer::doDelete($c, $con);

			// delete related Tb104BancoConciliacion objects
			$c = new Criteria(Tb104BancoConciliacionPeer::DATABASE_NAME);
			
			$c->add(Tb104BancoConciliacionPeer::ID_TB011_CUENTA_BANCARIA, $obj->getCoCuentaBancaria());
			$affectedRows += Tb104BancoConciliacionPeer::doDelete($c, $con);

			// delete related Tb105Conciliacion objects
			$c = new Criteria(Tb105ConciliacionPeer::DATABASE_NAME);
			
			$c->add(Tb105ConciliacionPeer::ID_TB011_CUENTA_BANCARIA, $obj->getCoCuentaBancaria());
			$affectedRows += Tb105ConciliacionPeer::doDelete($c, $con);
		}
		return $affectedRows;
